"use client";
import { useState, useEffect, useRef } from "react";
import Image from "next/image";
import Breadcrumb from "@/components/header/breadcrumb";
import getConversations from "@/services/support/getConversations";
import sendMessage from "@/services/support/sendMessage";
import styles from "./style.module.scss";

export default function Page({ searchParams }: { searchParams: any }) {
  const [sendLoading, setSendLoading] = useState(false);
  const [dataLoading, setDataLoading] = useState(true);
  const [data, setData] = useState([]);
  const [message, setMessage] = useState("");
  const [errorMessage, setErrorMessage] = useState("");
  const divRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    divRef?.current?.scroll({
      top: divRef?.current?.scrollHeight,
      behavior: "smooth",
    });
  };

  const getData = async () => {
    setDataLoading(true);
    await getConversations({
      slug: searchParams.slug,
      key: searchParams.key,
    }).then((res) => {
      setData(res);
      setDataLoading(false);
    });
  };

  const sendMessageSubmit = async () => {
    if (message) {
      setErrorMessage("");
      setSendLoading(true);
      try {
        setSendLoading(true);
        const res = await sendMessage({
          slug: searchParams.slug,
          key: searchParams.key,
          message,
        });
        setSendLoading(false);

        if (res.success) {
          getData();
        } else {
          setErrorMessage(
            "A problem occurred due to the system. Please try again later or contact customer service. Error message:" +
              res.message
          );
        }
      } catch (error: any) {
        setSendLoading(false);
        setErrorMessage(
          "A problem occurred due to the system. Please try again later or contact customer service."
        );
      }
    } else setErrorMessage("Please type a message.");
  };

  useEffect(() => {
    getData();
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    scrollToBottom();
  }, [data]); // eslint-disable-line react-hooks/exhaustive-deps

  if (dataLoading)
    return (
      <main>
        <div className="tw-max-w-[1320px] tw-mx-auto tw-px-4 tw-my-4 tw-font-display">
          <Breadcrumb items={[{ pageTitle: "Support", pageUrl: "/support" }]} />
          <h1 className="tw-text-[24px] tw-font-bold tw-text-[#14101c]">
            Support
          </h1>
          <div className="tw-text-center tw-my-4">
            <div
              className="tw-inline-block tw-rounded-full tw-border-4 tw-border-solid tw-border-[#854ec9] tw-border-r-transparent tw-animate-spin"
              role="status"
              style={{ width: 75, height: 75 }}
            >
              <span className="tw-sr-only">Loading...</span>
            </div>
            <p className="tw-text-[18px] tw-font-semibold tw-mt-4">
              Loading your support details.
              <br />
              Please wait.
            </p>
          </div>
        </div>
      </main>
    );

  return (
    <main>
      <div className="tw-max-w-[1320px] tw-mx-auto tw-px-4 tw-my-4 tw-font-display">
        <Breadcrumb items={[{ pageTitle: "Support", pageUrl: "/support" }]} />
        <h1 className="tw-text-[24px] tw-font-bold tw-text-[#14101c]">Support</h1>

        <div className="tw-my-4 tw-rounded-2xl tw-border tw-border-solid tw-border-[#eceaf1] tw-bg-white tw-overflow-hidden">
          <div className="tw-relative">
            <div ref={divRef} className={`${styles.chatMessages} tw-px-4 tw-pt-4`}>
              {data.map((item: any, index: number) => (
                <div
                  className={`${
                    item.style == "left"
                      ? styles.chatMessageLeft
                      : styles.chatMessageRight
                  } tw-pb-4`}
                  key={index}
                >
                  <div>
                    <Image
                      src="/images/no-profile.png"
                      width={40}
                      height={40}
                      alt="Avatar"
                    />
                  </div>
                  <div
                    className={`${
                      item.style == "left" ? "tw-ml-3" : "tw-mr-3"
                    } tw-shrink tw-bg-[#f3f2f6] tw-rounded-lg tw-py-2 tw-px-3`}
                  >
                    <div className="tw-mb-1">
                      <strong className="tw-text-[#14101c]">
                        {item.author.name}
                      </strong>
                    </div>
                    <p className="tw-mb-2 tw-text-[15px] tw-text-[#14101c]">
                      {item.content}
                    </p>
                    <span className="tw-text-[12px] tw-italic tw-text-[#5d556c]">
                      {item.date}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          </div>

          <div
            className={`${styles.flexGrow0} tw-py-3 tw-px-4 tw-border-0 tw-border-t tw-border-solid tw-border-[#dee2e6]`}
          >
            <div className="tw-flex tw-flex-wrap tw-items-stretch">
              {errorMessage && (
                <div
                  role="alert"
                  className="tw-w-full tw-mb-2 tw-rounded-xl tw-border tw-border-solid tw-border-red-200 tw-bg-red-50 tw-px-4 tw-py-3 tw-text-[14px] tw-text-red-700"
                >
                  {errorMessage}
                </div>
              )}
              <div className="tw-w-full md:tw-w-3/4 tw-p-2">
                <input
                  type="text"
                  className="tw-w-full tw-rounded-xl tw-border tw-border-solid tw-border-[#d6d2de] tw-px-3.5 tw-py-2.5 tw-text-[15px] tw-text-[#14101c] tw-outline-none focus:tw-border-[#854ec9] tw-transition-colors"
                  placeholder="Type your message"
                  onChange={(e) => {
                    setMessage(e.target.value);
                  }}
                />
              </div>
              <div className="tw-w-full md:tw-w-1/4 tw-p-2">
                {sendLoading ? (
                  <button
                    className="tw-w-full tw-inline-flex tw-items-center tw-justify-center tw-gap-1 tw-rounded-full tw-bg-[#854ec9] tw-text-white tw-font-semibold tw-text-[15px] tw-px-4 tw-py-2.5 tw-border-0 tw-cursor-not-allowed tw-opacity-60"
                    type="button"
                    disabled
                  >
                    <span
                      className="tw-inline-block tw-w-4 tw-h-4 tw-mr-1 tw-rounded-full tw-border-2 tw-border-solid tw-border-current tw-border-r-transparent tw-animate-spin tw-align-[-0.125em]"
                      aria-hidden="true"
                    ></span>
                    <span role="status"> Loading...</span>
                  </button>
                ) : (
                  <button
                    type="button"
                    className="tw-w-full tw-inline-flex tw-items-center tw-justify-center tw-rounded-full tw-bg-[#854ec9] hover:tw-bg-[#6a3da4] tw-text-white tw-font-semibold tw-text-[15px] tw-px-4 tw-py-2.5 tw-border-0 tw-cursor-pointer tw-transition-colors"
                    onClick={sendMessageSubmit}
                  >
                    Send Message
                  </button>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </main>
  );
}
