import { apiClient } from "@/lib/apiClient";

// apiv3 B2C: POST /customer/support/send — destek sohbetine mesaj gönder.
// Yanıt {success, data} veya {success:false, message} (her durumda 200).
export default async function sendMessage({ slug, key, message }: { slug: string; key: string; message: string }) {
  return apiClient("/customer/support/send", {
    method: "POST",
    body: { slug, key, message },
  });
}
