import { apiClient } from "@/lib/apiClient";

// apiv3 B2C: GET /customer/support?slug=&key= — eski enquiry/ticket destek sohbeti.
// Tüm durumlar 200 döner (başarıda mesaj dizisi, hata durumunda {success:false,...}).
export default async function getConversations({ slug, key }: { slug: string; key: string }) {
  return apiClient(`/customer/support?slug=${slug}&key=${key}`);
}
